{
  "name": "Robotiq Hand-E机械夹爪",
  "name_en": "Robotiq Hand-E Gripper",
  "manufacturer": "Robotiq",
  "description": "用于机器人末端执行器的两指电动夹爪，可通过网络套接字直接连接并控制，支持激活、开闭状态判断、开合位置自动校准，以及按目标位置、速度和力执行夹持运动，适合实验自动化中的样品抓取与转运。",
  "description_en": "A two-finger electric robotic gripper used as an end effector, directly controlled over a network socket. It supports activation, open/closed state checks, automatic calibration of open and closed positions, and gripping motions with commanded position, speed, and force for sample handling and transfer in lab automation.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到夹爪设备。",
      "description_en": "Connect to the gripper."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与夹爪设备的连接。",
      "description_en": "Disconnect from the gripper."
    },
    {
      "action_name": "auto-activate",
      "description": "激活夹爪，并可选择自动校准开合范围。",
      "description_en": "Activate the gripper, optionally with automatic calibration of its open/close range."
    },
    {
      "action_name": "auto-is_active",
      "description": "检查夹爪是否已激活。",
      "description_en": "Check whether the gripper is active."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查夹爪是否处于完全打开状态。",
      "description_en": "Check whether the gripper is fully open."
    },
    {
      "action_name": "auto-is_closed",
      "description": "检查夹爪是否处于完全闭合状态。",
      "description_en": "Check whether the gripper is fully closed."
    },
    {
      "action_name": "auto-auto_calibrate",
      "description": "自动校准夹爪的最小和最大位置范围。",
      "description_en": "Automatically calibrate the gripper's minimum and maximum position range."
    },
    {
      "action_name": "auto-move",
      "description": "按指定位置、速度和力控制夹爪运动。",
      "description_en": "Move the gripper using the specified position, speed, and force."
    },
    {
      "action_name": "auto-move_and_wait_for_pos",
      "description": "按指定位置、速度和力控制夹爪运动，并等待运动完成。",
      "description_en": "Move the gripper using the specified position, speed, and force, and wait for completion."
    },
    {
      "action_name": "auto-get_closed_position",
      "description": "获取定义的闭合位置。",
      "description_en": "Get the defined closed position."
    },
    {
      "action_name": "auto-get_current_position",
      "description": "获取当前夹爪位置。",
      "description_en": "Get the current gripper position."
    },
    {
      "action_name": "auto-get_max_position",
      "description": "获取最大可达位置。",
      "description_en": "Get the maximum reachable position."
    },
    {
      "action_name": "auto-get_min_position",
      "description": "获取最小可达位置。",
      "description_en": "Get the minimum reachable position."
    },
    {
      "action_name": "auto-get_open_position",
      "description": "获取定义的打开位置。",
      "description_en": "Get the defined open position."
    }
  ],
  "tag_hints": [
    "robot gripper",
    "two-finger gripper",
    "end effector",
    "gripping force control",
    "position control",
    "sample handling",
    "lab automation",
    "Robotiq Hand-E"
  ]
}

